--[=[
    @interface INZViewModel
    视图模型接口定义，负责管理视图和模型之间的交互
]=]
export type INZViewModel = {
    --[=[
        创建新的ViewModel实例
        @param vmScript ModuleScript ViewModel脚本
        @return INZViewModel
    ]=]
    new: (vmScript: any) -> INZViewModel,

    --[=[
        生命周期方法 - 加载
    ]=]
    Load: (self: INZViewModel) -> (),

    --[=[
        生命周期方法 - 启动
    ]=]
    Start: (self: INZViewModel) -> (),

    --[=[
        响应数据变化
        @param name string 数据路径
    ]=]
    Respond: (self: INZViewModel, name: string) -> (),

    --[=[
        连接事件
        @param ... any 连接参数
        @return Connection
    ]=]
    Connect: (self: INZViewModel, ...any) -> any,

    --[=[
        绑定命令
        @param ... any 绑定参数
        @return Connection
    ]=]
    Bind: (self: INZViewModel, ...any) -> any,

    --[=[
        注册窗口、面板或容器
        @param name string 名称
        @param _type "Window" | "Panel" | "Sprite" | "Container" 类型
    ]=]
    Register: (self: INZViewModel, name: string, _type: string) -> (),

    --[=[
        添加容器
        @param container any 容器对象
        @param windowName string 窗口名称
    ]=]
    AddContainer: (self: INZViewModel, container: any, windowName: string) -> (),

    --[=[
        打开窗口
        @param windowName string 窗口名称
        @param ... any 额外参数
    ]=]
    Open: (self: INZViewModel, windowName: string, ...any) -> (),

    --[=[
        关闭窗口
        @param windowName string 窗口名称
        @param ... any 额外参数
    ]=]
    Close: (self: INZViewModel, windowName: string, ...any) -> (),

    --[=[
        返回上一个窗口
        @param windowName string 窗口名称
        @param ... any 额外参数
    ]=]
    Back: (self: INZViewModel, windowName: string, ...any) -> (),

    --[=[
        获取容器
        @param container string 容器名称
        @return any 容器对象
    ]=]
    GetContainer: (self: INZViewModel, container: string) -> any,

    --[=[
        显示面板
        @param containerName string 容器名称
        @param panelName string 面板名称
        @param ... any 额外参数
    ]=]
    ShowPanel: (self: INZViewModel, containerName: string, panelName: string, ...any) -> (),

    --[=[
        隐藏面板
        @param containerName string 容器名称
        @param panelName string 面板名称
        @param ... any 额外参数
    ]=]
    HidePanel: (self: INZViewModel, containerName: string, panelName: string, ...any) -> (),

    --[=[
        推入面板
        @param containerName string 容器名称
        @param panelName string 面板名称
        @param ... any 额外参数
    ]=]
    PushPanel: (self: INZViewModel, containerName: string, panelName: string, ...any) -> (),

    --[=[
        弹出面板
        @param containerName string 容器名称
        @param panelName string 面板名称
        @param ... any 额外参数
    ]=]
    PopPanel: (self: INZViewModel, containerName: string, panelName: string, ...any) -> (),

    --[=[
        清理面板
        @param containerName string 容器名称
        @param ... any 额外参数
    ]=]
    CleanPanel: (self: INZViewModel, containerName: string, ...any) -> (),
}

return {}